namespace Deployment {
QString GroupDigest(QJsonObject group){group.remove("name");return Sha(Json(group));}
namespace {
QJsonObject Object(QJsonValue value){Require(value.isObject(),"Expected configuration object");return value.toObject();}
QString Proxy(const QString &object,const HardwareBoardSetup &board,int port){Require(!object.isEmpty() && !object.contains(':') && !object.contains(' ') && !object.contains("REPLACE"),"Set the board service object in Advanced");return object+":tcp -h "+Address(board.address)+" -p "+QString::number(Port(port));}
QString Instance(const QString &group,const QString &receiver){return Id(group+"-"+receiver);}
}
HardwareDeploymentSetup SuggestGroupPorts(HardwareDeploymentSetup setup,const QString &eccNode,const QString &defaultReceiverNode,const QJsonArray &groups,const QJsonArray &nodes){
    QMap<QString,QSet<int>> used;
    auto reserve=[&](const QString &host,int port){if(port>0 && port<=65535)used[host].insert(port);};
    for(const auto &value:nodes){const auto node=value.toObject();reserve(node["id"].toString(),QUrl(node["url"].toString()).port());}
    for(const auto &value:groups){
        const auto group=value.toObject(),ecc=group["ecc"].toObject();const auto host=ecc["node_id"].toString();reserve(host,ecc["port"].toInt());
        for(int i=0;i<group["policies"].toArray().size();++i)reserve(host,ecc["callback_port"].toInt()+i);
        for(const auto &rxValue:group["receivers"].toArray()){
            const auto rx=rxValue.toObject();const auto receiverHost=rx["node_id"].toString();reserve(receiverHost,rx["port"].toInt());
            for(const auto &sourceValue:rx["sources"].toArray()){const auto source=sourceValue.toObject();for(const auto &key:{"data_port","status_port","export_port"})reserve(receiverHost,source[key].toInt());}
        }
    }
    auto take=[&](const QString &host,int first,int count){for(int port=first;port<=65535-count+1;++port){bool free=true;for(int i=0;i<count;++i)if(used[host].contains(port+i)){free=false;break;}if(free){for(int i=0;i<count;++i)reserve(host,port+i);return port;}}throw std::runtime_error("No free port range remains in this project's host assignments");};
    setup.eccPort=take(eccNode,24000,1);
    setup.callbackPort=take(eccNode,24100,qMax(1,setup.boards.size()));
    QSet<QString> receiving;for(auto &board:setup.boards)if(board.receivesData){if(board.receiverNodeId.isEmpty())board.receiverNodeId=defaultReceiverNode;receiving.insert(board.receiverNodeId);}
    auto hosts=receiving.values();hosts.sort();
    // The GUI creates supervisors in the same host order, at base + index.
    bool assigned=false;for(int base=24001;base<=65535-qMax(1,hosts.size())+1;++base){bool free=true;for(int i=0;i<hosts.size();++i)if(used[hosts[i]].contains(base+i)){free=false;break;}if(free){setup.supervisorPort=base;for(int i=0;i<hosts.size();++i)reserve(hosts[i],base+i);assigned=true;break;}}
    Require(assigned,"No receiver management port range remains in this project");
    for(auto &board:setup.boards)if(board.receivesData){board.dataPort=take(board.receiverNodeId,24300,1);board.statusPort=take(board.receiverNodeId,24301,1);}
    return setup;
}
QJsonObject CompileGroup(const HardwareDeploymentSetup &setup,const QString &groupId,const QString &eccNode,const QString &eccAddress,const QJsonArray &receivers,QMap<QString,QByteArray> *files,const QMap<QString,QByteArray> &existingFiles){
    Id(groupId);Id(eccNode);Address(eccAddress);Address(setup.callbackAddress);Port(setup.eccPort);Port(setup.callbackPort);
    auto artifact=CompileHardwareSetupExperiment(setup.experimentFile,setup.profileFile);const auto original=artifact.settings;artifact.settings.cobos.clear();artifact.settings.mutants.clear();
    const auto profileName=groupId+"-profile.json";QByteArray profile;
    if(!setup.profileFile.isEmpty())profile=Read(setup.profileFile,1024*1024);else profile=existingFiles.value(profileName);
    Require(!profile.isEmpty() && Sha(profile)==QString::fromStdString(artifact.profileSha256),"The complete source profile is required for distributed publication");files->insert(profileName,profile);
    QJsonArray sourceMapping;int sourceIndex=0;
    for(auto &source:artifact.sources){const auto previous=QString::fromStdString(source.path);QByteArray bytes;if(previous.startsWith("bundle://")){Require(existingFiles.contains(previous.mid(9)),"Missing imported source bytes");bytes=existingFiles.value(previous.mid(9));}else bytes=Read(previous,16*1024*1024);Require(Sha(bytes)==QString::fromStdString(source.sha256),"Experiment source changed before publication");const auto name=groupId+"-source-"+QString::number(sourceIndex++)+".xcfg";files->insert(name,bytes);source.path=("bundle://"+name).toStdString();sourceMapping.append(QJsonObject{{"file",name},{"sha256",Sha(bytes)}});}
    QJsonArray cobos,mutants,descriptions,policies,senders;QSet<QString> ids;QMap<QString,const HardwareBoardSetup *> boards;
    for(int i=0;i<setup.boards.size();++i){const auto &board=setup.boards[i];Id(board.id);Require(!ids.contains(board.id),"Duplicate board ID in group");ids.insert(board.id);boards[board.id]=&board;const auto source=(board.templateId.isEmpty()?board.id:board.templateId).toStdString();bool found=false;
        if(board.mutant){for(auto value:original.mutants)if(value.id==source){Require(board.receivesData==value.settings.readoutEnabled,"MuTaNT readout differs from its template");value.id=board.id.toStdString();artifact.settings.mutants.push_back(value);found=true;break;}}
        else for(auto value:original.cobos)if(value.id==source){value.id=board.id.toStdString();value.enabled=board.enabled;artifact.settings.cobos.push_back(value);found=true;break;}
        Require(found,"No electronics template for board: "+board.id);
        QByteArray description;if(board.descriptionFile.endsWith(".json",Qt::CaseInsensitive))description=Read(board.descriptionFile,8*1024*1024);else{XcfgDocument doc;QJsonObject object;QString error;Require(doc.Load(board.descriptionFile,&error) && HardwareCompiler::Compile(doc,&object,&error),error);description=QJsonDocument(object).toJson();}
        GetDAQ::DecodeHardwareDescription(description.toStdString());const auto name=groupId+"-hardware-"+QString::number(i)+".json";files->insert(name,description);descriptions.append(name);
        QJsonObject node{{"id",board.id},{"expected_node_name",board.nodeName},{"node_proxy",Proxy(board.nodeObject,board,board.controlPort)},{"hardware_description_file",name}};
        if(board.mutant){node["role"]=board.mutantRole;node["alignment_proxy"]=Proxy(board.alignmentObject,board,board.controlPort);mutants.append(node);}else{node["enabled"]=board.enabled;node["link_proxy"]=Proxy(board.linkObject,board,board.controlPort);cobos.append(node);policies.append(QJsonObject{{"id",board.id},{"callback_endpoints",QString("tcp -h %1 -p %2").arg(setup.callbackAddress).arg(setup.callbackPort+i)},{"published_endpoints",""},{"max_pending_alarms",1024},{"max_alarm_audit_bytes",16777216}});}
    }
    GetDAQ::ValidateSystemExperimentSettings(artifact.settings);artifact.configurationSha256=GetDAQ::SystemExperimentDigest(artifact.settings);
    const auto artifactBytes=QByteArray::fromStdString(GetDAQ::EncodeSystemExperimentArtifact(artifact));const auto artifactName=groupId+"-experiment.json",topologyName=groupId+"-topology.json";
    files->insert(artifactName,artifactBytes);files->insert(topologyName,Json({{"schema_version",1},{"kind","getdaq.alignment-topology"},{"encoding","1.0"},{"timeout_ms",3000},{"cobos",cobos},{"mutants",mutants}}));
    QMap<QString,unsigned> masks;for(const auto &board:artifact.settings.cobos)if(board.enabled)masks[QString::fromStdString(board.id)]=GetDAQ::CompileCoBoConfigure(board.configure).readout.aget.asadMask;
    QSet<QString> assigned;QJsonArray placements;
    for(const auto &value:receivers){auto placement=Object(value);Id(placement["id"].toString());Instance(groupId,placement["id"].toString());Id(placement["node_id"].toString());Address(placement["address"].toString());Port(placement["port"].toInt());QJsonArray sources;
        for(const auto &senderValue:placement["sender_ids"].toArray()){const auto id=senderValue.toString();Require(boards.contains(id) && !assigned.contains(id),"Missing or duplicate receiver assignment");const auto &board=*boards[id];Require(board.receivesData,"Receiver assigned to inactive board");assigned.insert(id);const auto receiver=Address(board.receiverAddress)+':'+QString::number(Port(board.dataPort));Port(board.statusPort);
            sources.append(QJsonObject{{"id",id},{"receiver_address",receiver},{"bind",board.receiverAddress},{"data_port",board.dataPort},{"status_port",board.statusPort},{"export_port",0},{"queue_mib",64},{"max_frame_mib",32},{"rotate_mib",1024},{"export_queue_mib",16},{"min_free_mib",2048}});
            senders.append(QJsonObject{{"id",id},{"control_proxy",Proxy(board.senderObject,board,board.senderPort)},{"receiver_address",receiver},{"circular_buffer_mask",board.mutant?1:int(masks[id])},{"always_flush",false},{"exclusive_stopped_owner_confirmed",true},{"encoding_minor",0},{"timeout_ms",3000}});
        }Require(!sources.isEmpty(),"Empty receiver service assignment");placement.remove("sender_ids");placement["sources"]=sources;placements.append(placement);
    }
    for(const auto &board:setup.boards)Require(!board.receivesData || assigned.contains(board.id),"Board has no receiving host: "+board.id);
    const QJsonObject group{{"id",groupId},{"artifact_file",artifactName},{"profile_file",profileName},{"topology_file",topologyName},{"descriptions",descriptions},{"configuration_sha256",QString::fromStdString(artifact.configurationSha256)},{"artifact_sha256",Sha(artifactBytes)},{"sources",sourceMapping},{"policies",policies},{"senders",senders},{"receivers",placements},{"accept_delay_warning",setup.acceptLegacyDelayReadback},{"ecc",QJsonObject{{"node_id",eccNode},{"address",eccAddress},{"port",setup.eccPort},{"callback_address",setup.callbackAddress},{"callback_port",setup.callbackPort}}}};
    ValidateGroupFiles(group,*files);return group;
}
void ValidateGroupFiles(const QJsonObject &group,const QMap<QString,QByteArray> &files){const auto artifactName=group["artifact_file"].toString();Require(files.contains(artifactName) && Sha(files.value(artifactName))==group["artifact_sha256"].toString(),"Group artifact bytes differ");const auto artifact=GetDAQ::DecodeSystemExperimentArtifact(files.value(artifactName).toStdString());Require(QString::fromStdString(artifact.configurationSha256)==group["configuration_sha256"].toString(),"Group parameter identity differs");Require(files.contains(group["profile_file"].toString()) && Sha(files.value(group["profile_file"].toString()))==QString::fromStdString(artifact.profileSha256),"Group profile bytes differ");for(const auto &source:artifact.sources){const auto path=QString::fromStdString(source.path);Require(path.startsWith("bundle://") && files.contains(path.mid(9)) && Sha(files.value(path.mid(9)))==QString::fromStdString(source.sha256),"Portable artifact source is not verified by this release");}Require(files.contains(group["topology_file"].toString()),"Group topology missing");for(const auto &file:group["descriptions"].toArray()){Require(files.contains(file.toString()),"Hardware description missing");GetDAQ::DecodeHardwareDescription(files.value(file.toString()).toStdString());}}
void ValidateRelease(const QJsonObject &manifest){Require(manifest.size()==6 && manifest["schema"].toInt()==1 && manifest["kind"]=="getdaq.distributed-release","Unsupported distributed release");Id(manifest["project_id"].toString());const auto hosts=manifest["hosts"].toArray(),groups=manifest["groups"].toArray(),files=manifest["files"].toArray();Require(!hosts.isEmpty() && hosts.size()<=64 && !groups.isEmpty() && groups.size()<=64 && !files.isEmpty() && files.size()<=512,"Distributed release budget exceeded");QSet<QString> hostIds,groupIds,fileIds,boards;QMap<QString,QSet<int>> ports;
    for(const auto &host:hosts){const auto object=Object(host);const auto id=Id(object["id"].toString());Require(!hostIds.contains(id),"Duplicate node identity");hostIds.insert(id);}
    for(const auto &file:files){const auto entry=Object(file);const auto id=Id(entry["id"].toString());Require(!fileIds.contains(id),"Duplicate file identity");fileIds.insert(id);Digest(entry["sha256"].toString());Require(entry["bytes"].toDouble()>0 && entry["bytes"].toDouble()<=16*1024*1024 && entry["objects"].toArray().size()>0 && entry["objects"].toArray().size()<=512,"Invalid content size");for(const auto &chunk:entry["objects"].toArray())Digest(chunk.toString());}
    auto reserve=[&](const QString &node,int port){Require(hostIds.contains(node),"Instance refers to an unregistered node");Port(port);Require(!ports[node].contains(port),"Two services on one node use the same port");ports[node].insert(port);};
    for(const auto &value:groups){const auto group=Object(value);const auto id=Id(group["id"].toString());Require(!groupIds.contains(id),"Duplicate control group");groupIds.insert(id);Digest(group["configuration_sha256"].toString());Digest(group["artifact_sha256"].toString());Require(fileIds.contains(group["artifact_file"].toString()) && fileIds.contains(group["topology_file"].toString()),"Group file reference missing");const auto ecc=Object(group["ecc"]);reserve(ecc["node_id"].toString(),ecc["port"].toInt());Address(ecc["address"].toString());Address(ecc["callback_address"].toString());int index=0;for(const auto &policy:group["policies"].toArray()){Q_UNUSED(policy);reserve(ecc["node_id"].toString(),ecc["callback_port"].toInt()+index++);}
        QMap<QString,QString> sources;QSet<QString> receiverIds;for(const auto &receiverValue:group["receivers"].toArray()){const auto receiver=Object(receiverValue);const auto rx=Id(receiver["id"].toString());Require(!receiverIds.contains(rx),"Duplicate receiver identity");receiverIds.insert(rx);reserve(receiver["node_id"].toString(),receiver["port"].toInt());Address(receiver["address"].toString());for(const auto &sourceValue:receiver["sources"].toArray()){const auto source=Object(sourceValue);const auto sender=Id(source["id"].toString());Require(!sources.contains(sender),"Source assigned to multiple receiving services");Address(source["bind"].toString());reserve(receiver["node_id"].toString(),source["data_port"].toInt());reserve(receiver["node_id"].toString(),source["status_port"].toInt());Require(source["receiver_address"].toString()==source["bind"].toString()+':'+QString::number(source["data_port"].toInt()),"Receiver address differs from its data port");sources[sender]=source["receiver_address"].toString();}}
        Require(!sources.isEmpty(),"Control group requires receiving sources");QSet<QString> senders;for(const auto &senderValue:group["senders"].toArray()){const auto sender=Object(senderValue);const auto name=sender["id"].toString(),proxy=sender["control_proxy"].toString();Require(!senders.contains(name) && sources.value(name)==sender["receiver_address"].toString(),"Sender/receiver mapping differs");senders.insert(name);Require(!boards.contains(proxy),"A board sender belongs to more than one ECC");boards.insert(proxy);}Require(senders.size()==sources.size(),"Extra receiver source");
    }
}
Bundle BuildBundle(const QString &projectId,const QJsonArray &hosts,const QJsonArray &groups,const QMap<QString,QByteArray> &files){Bundle bundle;QJsonArray entries;qint64 total=0;for(auto it=files.begin();it!=files.end();++it){Id(it.key());Require(!it.value().isEmpty() && it.value().size()<=16*1024*1024,"Invalid release file size");total+=it.value().size();Require(total<=64*1024*1024,"Release content exceeds 64 MiB");QJsonArray chunks;for(int offset=0;offset<it.value().size();offset+=32768){const auto bytes=it.value().mid(offset,32768);const auto sha=Sha(bytes);bundle.objects[sha]=bytes;chunks.append(sha);}entries.append(QJsonObject{{"id",it.key()},{"sha256",Sha(it.value())},{"bytes",it.value().size()},{"objects",chunks}});}bundle.manifest={{"schema",1},{"kind","getdaq.distributed-release"},{"project_id",Id(projectId)},{"hosts",hosts},{"groups",groups},{"files",entries}};ValidateRelease(bundle.manifest);for(const auto &group:groups)ValidateGroupFiles(group.toObject(),files);Require(Json(bundle.manifest).size()<=1024*1024,"Release manifest exceeds limit");return bundle;}
QByteArray Assemble(const QJsonObject &file,const QMap<QString,QByteArray> &objects){QByteArray bytes;const auto chunks=file["objects"].toArray();for(int i=0;i<chunks.size();++i){const auto sha=Digest(chunks[i].toString());Require(objects.contains(sha) && Sha(objects.value(sha))==sha,"Content chunk missing or damaged");const auto part=objects.value(sha);Require(part.size()>0 && part.size()<=32768 && (i==chunks.size()-1 || part.size()==32768),"Invalid content chunk size");bytes+=part;Require(bytes.size()<=16*1024*1024,"Assembled content exceeds budget");}Require(bytes.size()==file["bytes"].toInt() && Sha(bytes)==file["sha256"].toString(),"Assembled file differs");return bytes;}
QMap<QString,QByteArray> ReadBundleFiles(const Bundle &bundle){QMap<QString,QByteArray> files;for(const auto &file:bundle.manifest["files"].toArray())files[file.toObject()["id"].toString()]=Assemble(file.toObject(),bundle.objects);return files;}
QString UploadBundle(const Endpoint &endpoint,const QString &repositoryId,const Bundle &bundle){ValidateRelease(bundle.manifest);Require(Get(endpoint,"/v1/identity")["repository_id"].toString()==Digest(repositoryId),"Repository identity changed");const QMap<QByteArray,QByteArray> headers{{"X-Repository-ID",repositoryId.toLatin1()}};auto upload=[&](const QByteArray &bytes){const auto sha=Sha(bytes);if(!Get(endpoint,"/v1/objects/"+sha)["present"].toBool()){const auto response=Request(endpoint,"POST","/v1/objects/"+sha,bytes,"application/octet-stream",headers);Require(response.code==200,"Content upload failed");}return sha;};for(auto it=bundle.objects.begin();it!=bundle.objects.end();++it){Require(Sha(it.value())==it.key(),"Content map identity differs");upload(it.value());}const auto bytes=Json(bundle.manifest);QJsonArray chunks;for(int offset=0;offset<bytes.size();offset+=32768)chunks.append(upload(bytes.mid(offset,32768)));const auto receipt=Post(endpoint,"/v1/deployments",{{"manifest_objects",chunks}},headers);Require(receipt["release_id"].toString()==Sha(bytes) && receipt["repository_id"].toString()==repositoryId && receipt["content_verified"].toBool(),"Release registration receipt differs");return Sha(bytes);}
}
